window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["computer-use"]={"title":"计算机使用智能体：在观察、动作与状态验证之间闭环","subtitle":"从截图、DOM与可访问性树的动作接地，到焦点、幂等、权限和恢复，理解为什么“会点按钮”远不等于可靠完成任务。","thesis":"计算机使用智能体将视觉或语义界面状态映射成鼠标键盘动作；真正困难是每一步都确认<b>当前状态、动作目标、结果变化与副作用边界</b>，而不是记住一串坐标。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"输入 128.50","rule":"提交前展示差异并批准","steps":"超时先查询","interpretation":"编号出现才表示业务完成"}}],"formulas":[{"id":"computer-use-safe-action","section":4,"formulaIndex":1,"symbols":[{"name":"A","meaning":"当前界面动作是否满足全部执行条件","evidence":"A 表示当前动作是否允许"},{"name":"Target","meaning":"目标控件的角色名称和上下文是否匹配","evidence":"Target 表示目标控件匹配"},{"name":"State","meaning":"页面、焦点和选择状态等前置条件是否满足","evidence":"State 表示页面与焦点前置条件满足"},{"name":"Permission","meaning":"当前主体是否获准操作目标资源","evidence":"Permission 表示主体对资源有权操作"},{"name":"Bound","meaning":"动作后果是否可控、可撤销或已经批准","evidence":"Bound 表示后果可控或已批准"}]}],"termReviews":[{"section":2,"reviewedAt":"2026-07-27","terms":[{"name":"DOM","meaning":"浏览器对网页元素、属性和层级关系的结构化表示","purpose":"用元素语义和属性定位网页控件","definitionEvidence":"网页结构与属性丰富","purposeEvidence":"语义定位"},{"name":"可访问性树","meaning":"按角色、名称和可操作性呈现界面的辅助技术结构","purpose":"以跨视觉样式的语义信息定位控件","definitionEvidence":"角色、名称与可操作性","purposeEvidence":"优先使用角色名称等语义定位"}]},{"section":5,"reviewedAt":"2026-07-27","terms":[{"name":"状态差分","meaning":"比较动作前后可观察界面与业务状态的变化","purpose":"验证动作是否产生预期结果并决定下一步","definitionEvidence":"动作前观察、候选动作和动作后新观察","purposeEvidence":"输出继续、恢复或终止"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"计算机使用智能体是观察动作再验证的反馈控制器。","evidence":"计算机使用智能体是根据界面观察选择鼠标键盘动作并用新状态验证结果的反馈控制器"},"problem":{"answer":"它解决没有稳定 API 时的界面操作问题。","evidence":"解决没有稳定 API 时的界面操作"},"inputOutput":{"answer":"输入目标权限界面条件，输出动作和业务状态。","evidence":"输入是目标、主体权限、截图或结构和完成条件，输出是受限动作与业务状态"},"mechanism":{"answer":"在观察动作新观察循环中不断更新状态。","evidence":"观察—动作—新观察循环"},"interpretation":{"answer":"看到按钮只表示像素或节点存在。","evidence":"单次看到按钮只表示像素或节点存在"},"boundary":{"answer":"它不证明可点击获权或任务完成。","evidence":"不证明可点击、获权或任务已完成"}},{"section":2,"definition":{"answer":"截图 DOM 和可访问性树是互补观察通道。","evidence":"三种观察通道互补"},"problem":{"answer":"它解决坐标和语义结构哪种更可靠的问题。","evidence":"哪一个最可靠"},"inputOutput":{"answer":"输入应用和界面信息，输出单一或组合观察。","evidence":"输入应用类型、界面结构和可用辅助信息，输出截图、DOM、可访问性树或组合观察"},"mechanism":{"answer":"语义优先视觉验证坐标绑定几何。","evidence":"优先使用角色名称等语义定位"},"interpretation":{"answer":"任一通道只呈现局部界面状态。","evidence":"任一通道都只呈现局部状态"},"boundary":{"answer":"后台焦点权限仍需外部检查。","evidence":"后台事实、焦点和权限仍需外部检查"}},{"section":3,"definition":{"answer":"报销案例展示填写上传批准提交和回执验证。","evidence":"安全地填写并提交一张报销单"},"problem":{"answer":"它解决从打开页面到提交要验证哪些状态。","evidence":"哪些状态必须逐步验证"},"inputOutput":{"answer":"输入身份金额收据说明，输出编号或未知状态。","evidence":"输入受信域名、用户身份、金额 128.50、收据和说明，输出报销编号或明确未知状态"},"mechanism":{"answer":"逐字段验值，提交前批准，超时先查询。","evidence":"提交前展示差异并批准，超时先查询"},"interpretation":{"answer":"编号出现才表示业务完成。","evidence":"编号出现才表示业务完成"},"boundary":{"answer":"点击发送和选择器关闭都不是完成证据。","evidence":"都不是完成证据"}},{"section":4,"definition":{"answer":"安全动作要求目标状态权限后果四项同时成立。","evidence":"四个布尔条件"},"problem":{"answer":"它解决点击动作至少需要哪些前置条件。","evidence":"至少需要哪些前置条件"},"inputOutput":{"answer":"输入四个条件，输出允许重新观察或升级。","evidence":"输入目标匹配、状态前置、权限和后果边界四个布尔条件，输出允许、重新观察或升级"},"mechanism":{"answer":"逻辑与要求全部为真，未知按未满足处理。","evidence":"任何未知都按未满足处理"},"interpretation":{"answer":"通过只表示当前动作满足声明条件。","evidence":"通过只说明当前动作满足已声明条件"},"boundary":{"answer":"它不保证内容可信或后续业务成功。","evidence":"不保证页面内容可信或后续业务结果成功"}},{"section":5,"definition":{"answer":"状态差分闭环在每个动作后重新观察和决策。","evidence":"状态差分闭环"},"problem":{"answer":"它避免长任务只在最后检查一次成功。","evidence":"为什么长任务不能只在最后检查一次成功"},"inputOutput":{"answer":"输入前观察动作后观察，输出继续恢复或终止。","evidence":"输入动作前观察、候选动作和动作后新观察，输出继续、恢复或终止"},"mechanism":{"answer":"每步重新定位并检查业务回执。","evidence":"每步重新定位并检查业务回执"},"interpretation":{"answer":"差分表示已观察到的变化。","evidence":"差分只覆盖可观察变化"},"boundary":{"answer":"后台异步副作用仍需权威查询。","evidence":"仍需业务 ID 或权威系统查询"}},{"section":6,"definition":{"answer":"可靠性控制处理焦点等待和重复提交事故。","evidence":"焦点、等待与重复提交是三类基础事故"},"problem":{"answer":"它防止页面无响应后重复点击造成双重付款。","evidence":"为什么可能产生双重付款"},"inputOutput":{"answer":"输入焦点等待动作幂等状态，输出操作决定。","evidence":"输入焦点、等待条件、动作类型、幂等键和前后状态，输出输入、等待、查询或单次提交决定"},"mechanism":{"answer":"条件等待，写超时先查，再从检查点恢复。","evidence":"写动作超时先查询"},"interpretation":{"answer":"幂等降低重复副作用。","evidence":"幂等降低重复副作用"},"boundary":{"answer":"它不能修复写错对象或金额。","evidence":"无法修复写错对象或错误金额"}},{"section":7,"definition":{"answer":"界面信任隔离把网页和 OCR 文本视为不可信数据。","evidence":"网页内容是数据"},"problem":{"answer":"它防止页面文字把自己提升成高优先级命令。","evidence":"不是给智能体的高优先级命令"},"inputOutput":{"answer":"输入外部文本秘密，输出数据和受控注入。","evidence":"输入网页、邮件、OCR 文本和拟使用秘密，输出标为不可信数据的内容及受控字段注入"},"mechanism":{"answer":"控制平面给指令，密钥库直达允许字段。","evidence":"秘密从密钥库直达指定字段"},"interpretation":{"answer":"界面要求不等于用户授权。","evidence":"“界面要求”不是“用户授权”"},"boundary":{"answer":"允许列表仍须测试间接提示注入。","evidence":"仍须测试间接提示注入"}},{"section":8,"definition":{"answer":"API/UI 选型选择稳定接口界面或混合路径。","evidence":"输出 API、UI 或混合执行路径"},"problem":{"answer":"它解释有浏览器能力后为何仍优先 API。","evidence":"为什么还应优先调用 API"},"inputOutput":{"answer":"输入接口稳定视觉遗留限制，输出执行路径。","evidence":"输入可用接口、稳定性、幂等、视觉需求和遗留限制，输出 API、UI 或混合执行路径"},"mechanism":{"answer":"核心数据走 API，必要最后一公里用 UI。","evidence":"核心数据优先 API"},"interpretation":{"answer":"UI 适合无接口跨应用或视觉状态任务。","evidence":"只有无接口、跨应用或必须观察视觉状态时使用 UI"},"boundary":{"answer":"选择 UI 不降低审计权限和回执要求。","evidence":"不表示可以降低审计和权限要求"}},{"section":9,"definition":{"answer":"扰动评测在布局环境和注入变化下验证任务。","evidence":"评测必须加入布局与环境扰动"},"problem":{"answer":"它解决单机跑通十次能否证明可靠的问题。","evidence":"能证明智能体可靠吗"},"inputOutput":{"answer":"输入任务与环境变化，输出质量副作用恢复指标。","evidence":"输入任务、分辨率、缩放、语言、网络、弹窗、会话和页面版本变化，输出任务、子目标、错误点击、重复副作用和恢复指标"},"mechanism":{"answer":"逐扰动运行并用业务状态判定完成。","evidence":"完成由业务状态判定"},"interpretation":{"answer":"单一环境成功只覆盖该环境。","evidence":"只覆盖单一环境"},"boundary":{"answer":"它不能证明跨布局和注入鲁棒。","evidence":"不能证明跨布局和注入鲁棒"}},{"section":11,"definition":{"answer":"语义检查点保存已验证业务状态用于跨崩溃恢复。","evidence":"长任务恢复依赖语义检查点"},"problem":{"answer":"它解决浏览器崩溃后为何不能续第十七次点击。","evidence":"为什么不可靠"},"inputOutput":{"answer":"输入主体对象子目标回执，输出可恢复状态。","evidence":"输入已验证主体、对象 ID、子目标、草稿、回执和下一步前置条件，输出可跨崩溃恢复的业务状态"},"mechanism":{"answer":"重开受信入口并重新定位，不复用旧句柄。","evidence":"不复用坐标和旧 DOM 句柄"},"interpretation":{"answer":"检查点表示已验证业务状态。","evidence":"已验证主体、对象 ID、子目标"},"boundary":{"answer":"结果未知必须查询而非重放动作。","evidence":"必须按幂等键查询而非重放动作"}},{"section":12,"definition":{"answer":"轨迹隐私最小化计算机操作审计中的敏感暴露。","evidence":"轨迹审计也要最小化敏感暴露"},"problem":{"answer":"它解决保存全屏截图带来的新泄漏风险。","evidence":"会带来什么新风险"},"inputOutput":{"answer":"输入轨迹和用途，输出脱敏有期限审计记录。","evidence":"输入截图、结构动作、键盘事件和调试用途，输出最小化、脱敏且有保留期的审计记录"},"mechanism":{"answer":"保存目标窗口差分，秘密仅记安全注入。","evidence":"秘密只记录已安全注入"},"interpretation":{"answer":"可复盘不等于保存全部屏幕。","evidence":"可复盘不等于保存全屏"},"boundary":{"answer":"无关通知客户数据密钥不得默认暴露。","evidence":"不得因调试默认暴露"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分截图、DOM和可访问性树观察；手工推演状态验证与恢复；设计敏感动作前的确认边界；在布局、网络和提示注入扰动下评测。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>界面自动化是部分可观察的控制问题<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">智能体看到一个“提交”按钮，为什么仍不知道能否点击？</p><p>截图只呈现当前像素，不包含后台状态、真实控件语义或动作后果；页面可能仍加载、焦点可能在别处、同名按钮可能多个。智能体必须在观察—动作—新观察循环中更新状态，并以外部完成条件判断成功，不能执行预先背好的点击脚本。</p><p>计算机使用智能体是根据界面观察选择鼠标键盘动作并用新状态验证结果的反馈控制器。输入是目标、主体权限、截图或结构和完成条件，输出是受限动作与业务状态。它解决没有稳定 API 时的界面操作；单次看到按钮只表示像素或节点存在，不证明可点击、获权或任务已完成。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>三种观察通道互补<span class=\"dd-badge eng\">感知</span></h2><p class=\"dd-lead\">坐标、DOM和可访问性树哪一个最可靠？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>通道</th><th>优势</th><th>失效</th></tr></thead><tbody><tr><td>截图/视觉</td><td>适用于任意UI与画布</td><td>缩放、遮挡、相似图标</td></tr><tr><td>DOM</td><td>网页结构与属性丰富</td><td>影子DOM、画布、动态ID</td></tr><tr><td>可访问性树</td><td>角色、名称与可操作性</td><td>标注缺失、桌面支持差异</td></tr></tbody></table></div><p>优先语义定位器，视觉用于补充和验证；坐标是最后手段并绑定截图、分辨率和窗口几何。</p><p>观察通道选择输入应用类型、界面结构和可用辅助信息，输出截图、DOM、可访问性树或组合观察。优先使用角色名称等语义定位，视觉补充验证，坐标绑定当前几何。任一通道都只呈现局部状态；后台事实、焦点和权限仍需外部检查。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整示例：安全地填写并提交一张报销单<span class=\"dd-badge eng\">案例推演</span></h2><p class=\"dd-lead\">从打开页面到确认提交，哪些状态必须逐步验证？</p><ol class=\"dd-steps\"><li>确认域名、登录主体和表单标题符合任务作用域。</li><li>按可访问名称定位“金额”，点击后验证焦点，再输入 <code>128.50</code>；读取字段值确认没有落入搜索框。</li><li>上传指定收据，检查文件名、大小和预览，不能只相信文件选择器已关闭。</li><li>填写说明后读取摘要，比较拟提交值与用户原始要求。</li><li>“提交”是不可逆边界：展示差异并取得批准，生成幂等键后点击一次。</li><li>等待明确成功条件（报销编号出现），若超时先查询记录，不盲目再点。</li></ol><p>每一步的输出都是下一步的新观察；“点击已发送”不是“业务已完成”。</p><p>报销案例输入受信域名、用户身份、金额 128.50、收据和说明，输出报销编号或明确未知状态。系统逐字段验证焦点和值，上传后检查文件，提交前展示差异并批准，超时先查询。编号出现才表示业务完成；“点击已发送”或选择器关闭都不是完成证据。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>动作接地要同时确认对象、状态和可逆性<span class=\"dd-badge math\">动作模型</span></h2><p class=\"dd-lead\">一个点击动作至少需要哪些前置条件？</p><div class=\"dd-formula\" data-formula-id=\"computer-use-safe-action\" data-display=\"mathml\"><math display=\"block\" aria-label=\"安全动作 A 等于目标匹配、状态前置、权限和后果边界四个布尔条件的逻辑与\"><mi>A</mi><mo>=</mo><mi>Target</mi><mo>∧</mo><mi>State</mi><mo>∧</mo><mi>Permission</mi><mo>∧</mo><mi>Bound</mi></math></div><p class=\"dd-formula-note\"><code>A</code> 表示当前动作是否允许；<code>Target</code> 表示目标控件匹配，<code>State</code> 表示页面与焦点前置条件满足，<code>Permission</code> 表示主体对资源有权操作，<code>Bound</code> 表示后果可控或已批准；∧ 表示四项必须同时成立。</p><p>target_match 验证控件角色、名称和邻近上下文；state_precondition 检查页面/焦点/选中状态；permission 校验当前用户与资源；consequence_bound 判断是否可撤销、是否需批准。任何一项未知都应重新观察或升级，而不是让模型“猜最可能”。</p><p>安全动作判定输入目标匹配、状态前置、权限和后果边界四个布尔条件，输出允许、重新观察或升级。四项逻辑与要求全部为真才执行，任何未知都按未满足处理。通过只说明当前动作满足已声明条件，不保证页面内容可信或后续业务结果成功。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：每个动作后都必须用状态差分闭环<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">为什么长任务不能只在最后检查一次成功？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 320\" role=\"img\" aria-label=\"目标和权限进入观察定位动作策略，敏感动作经批准后执行，再通过状态差分和完成条件决定继续恢复或终止\"><defs><marker id=\"cu28\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"22\" y=\"110\" width=\"115\" height=\"82\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"80\" y=\"138\" text-anchor=\"middle\" class=\"svg-t\">目标与边界</text><text x=\"80\" y=\"163\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">主体 · 域名</text><text x=\"80\" y=\"183\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">权限 · 完成条件</text><path d=\"M137,151 L182,151\" stroke=\"#788293\" marker-end=\"url(#cu28)\"/><rect x=\"187\" y=\"70\" width=\"150\" height=\"162\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"262\" y=\"100\" text-anchor=\"middle\" class=\"svg-t\">观察与定位</text><text x=\"262\" y=\"128\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">截图 / DOM / AX</text><text x=\"262\" y=\"152\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">窗口 / 焦点 / 加载</text><text x=\"262\" y=\"176\" text-anchor=\"middle\" class=\"svg-t\">选择动作</text><text x=\"262\" y=\"202\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">目标 + 前置条件</text><path d=\"M337,151 L382,151\" stroke=\"#788293\" marker-end=\"url(#cu28)\"/><rect x=\"387\" y=\"92\" width=\"135\" height=\"118\" rx=\"9\" fill=\"#21252d\" stroke=\"#cf7c72\"/><text x=\"454\" y=\"121\" text-anchor=\"middle\" class=\"svg-t\">执行安全门</text><text x=\"454\" y=\"147\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">敏感输入隔离</text><text x=\"454\" y=\"170\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">提交前差异批准</text><text x=\"454\" y=\"193\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">幂等 / 一次点击</text><path d=\"M522,151 L567,151\" stroke=\"#788293\" marker-end=\"url(#cu28)\"/><rect x=\"572\" y=\"70\" width=\"140\" height=\"162\" rx=\"9\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"642\" y=\"100\" text-anchor=\"middle\" class=\"svg-t\">新观察</text><text x=\"642\" y=\"127\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">状态差分</text><text x=\"642\" y=\"151\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">业务回执</text><text x=\"642\" y=\"177\" text-anchor=\"middle\" class=\"svg-t\">完成？</text><text x=\"642\" y=\"203\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">继续 / 恢复 / 终止</text><path d=\"M642,232 C642,290 262,290 262,232\" fill=\"none\" stroke=\"#8b76bd\" marker-end=\"url(#cu28)\"/><text x=\"452\" y=\"302\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">未完成：依据新状态重规划，不复用旧坐标</text></svg><figcaption>图 1　可靠计算机使用是反馈控制；动作之后的验证与动作本身同等重要。</figcaption></figure><p>状态差分闭环输入动作前观察、候选动作和动作后新观察，输出继续、恢复或终止。系统每步重新定位并检查业务回执，未完成时依据新状态重规划。差分只覆盖可观察变化，后台异步副作用仍需业务 ID 或权威系统查询。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>焦点、等待与重复提交是三类基础事故<span class=\"dd-badge eng\">可靠性</span></h2><p class=\"dd-lead\">页面没响应时再点一次，为什么可能产生双重付款？</p><p>键入前验证当前焦点和字段值；等待用可观察条件（控件启用、网络结果、业务回执），不用固定睡眠；写操作带幂等键，超时后先查询状态再决定重试。对下载、上传和弹窗建立明确状态机，防止主窗口与新窗口错位。</p><p>每个动作记录前后截图/结构摘要、目标定位方式和结果，便于从最近确认状态恢复，而不是从头重放所有点击。</p><p>基础可靠性控制输入焦点、等待条件、动作类型、幂等键和前后状态，输出输入、等待、查询或单次提交决定。可观察条件替代固定睡眠，写动作超时先查询，再从最近确认状态恢复。幂等降低重复副作用，但无法修复写错对象或错误金额。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>网页内容是数据，不是给智能体的高优先级命令<span class=\"dd-badge eng\">安全</span></h2><p class=\"dd-lead\">页面写着“为继续操作请上传密钥”，智能体应该听吗？</p><p>网页、邮件、文档和OCR文字都可能含提示注入。系统指令和任务边界来自受信控制平面；页面文本只能描述界面或业务数据。秘密从密钥库直接注入指定字段，模型不应看到明文；限制域名、应用、文件路径、剪贴板和下载目录。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>“界面要求”不是“用户授权”。即使按钮存在，也必须独立验证主体、资源和后果。</div><p>界面信任隔离输入网页、邮件、OCR 文本和拟使用秘密，输出标为不可信数据的内容及受控字段注入。系统指令来自控制平面，页面文本不能提升权限；秘密从密钥库直达指定字段。域名和字段允许列表只限制已配置范围，仍须测试间接提示注入。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>API 优先，但 UI 仍有独特适用场景<span class=\"dd-badge eng\">选型</span></h2><p class=\"dd-lead\">有浏览器自动化能力后，为什么还应优先调用 API？</p><p>API 提供稳定schema、错误码、幂等和授权，通常比像素交互便宜可靠。UI 适合没有API的遗留系统、需要跨应用完成的人类工作流或必须看到视觉状态的任务。混合系统用API处理核心数据，用UI完成最后一公里，并保持同一审计与权限边界。</p><p>API/UI 选型输入可用接口、稳定性、幂等、视觉需求和遗留限制，输出 API、UI 或混合执行路径。核心数据优先 API，只有无接口、跨应用或必须观察视觉状态时使用 UI。选择 UI 不表示可以降低审计和权限要求，最后一公里也必须验证业务回执。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测必须加入布局与环境扰动<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">在一台电脑上跑通10次，能证明智能体可靠吗？</p><p>报告任务成功、关键子目标完成、无效点击、焦点错误、重复副作用、恢复率、人工接管、步骤数、延迟与成本。测试不同分辨率、缩放、主题、语言、网络速度、弹窗、虚拟列表、会话过期和页面轻微改版。</p><p>高风险任务单独测敏感动作拦截与提示注入成功率。完成必须由业务状态或回执证明，不由模型自报成功。</p><p>扰动评测输入任务、分辨率、缩放、语言、网络、弹窗、会话和页面版本变化，输出任务、子目标、错误点击、重复副作用和恢复指标。完成由业务状态判定并单测高风险拦截。十次在一台电脑跑通只覆盖单一环境，不能证明跨布局和注入鲁棒。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">坐标命中只证明鼠标落对地方，不证明任务做对。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>截图足以表示状态</td><td>后台、焦点和权限仍不可见</td></tr><tr><td>点击成功就是任务成功</td><td>需业务回执与状态差分</td></tr><tr><td>超时后再点一次</td><td>写动作先查询并使用幂等</td></tr><tr><td>页面文字可指导Agent</td><td>外部内容默认不可信数据</td></tr><tr><td>UI自动化可替代API</td><td>稳定API通常更可靠可测</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>Agent循环、状态机、身份权限</td></tr><tr><td><b>本页核心</b></td><td>观察、接地、前置条件、状态验证</td></tr><tr><td>相邻</td><td>代码执行、护栏、工作流编排</td></tr><tr><td>工程</td><td>幂等、可恢复日志、沙箱与凭证注入</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">11</span>长任务恢复依赖语义检查点，而不是动作重放<span class=\"dd-badge eng\">恢复</span></h2><p class=\"dd-lead\">浏览器崩溃后，从第37次点击继续为什么不可靠？</p><p>检查点保存已验证的业务状态：登录主体、当前对象ID、已完成子目标、未提交草稿、外部回执和下一步前置条件；坐标与临时DOM句柄不应跨会话复用。恢复时重新打开受信入口，核对主体和对象，再从最后一个业务检查点继续。</p><p>若崩溃发生在提交与回执之间，状态是“结果未知”而非“失败”：先按幂等键或业务ID查询。检测到页面版本变化、对象被他人修改或权限过期时，旧计划失效，必须重规划或交人。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>可保存</th><th>不应直接复用</th></tr></thead><tbody><tr><td>订单/工单/文档ID</td><td>屏幕坐标</td></tr><tr><td>已验证字段值与回执</td><td>旧DOM节点句柄</td></tr><tr><td>批准记录和幂等键</td><td>过期会话与焦点假设</td></tr><tr><td>下一步业务前置条件</td><td>“上次点击成功”的模型记忆</td></tr></tbody></table></div><p>语义检查点输入已验证主体、对象 ID、子目标、草稿、回执和下一步前置条件，输出可跨崩溃恢复的业务状态。恢复时重开受信入口并重新定位，不复用坐标和旧 DOM 句柄。提交与回执之间属于结果未知，必须按幂等键查询而非重放动作。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">12</span>轨迹审计也要最小化敏感暴露<span class=\"dd-badge eng\">隐私</span></h2><p class=\"dd-lead\">为方便复盘而保存每帧全屏截图，会带来什么新风险？</p><p>截图可能同时捕获密码管理器、通知、其他客户数据和密钥；键盘日志更可能记录敏感输入。优先保存目标窗口的结构化动作、必要状态差分和脱敏截图，秘密字段只记录“已安全注入”而非值。按任务风险设置保留期、访问权限与删除流程，调试人员不应默认看到生产全屏轨迹。</p><p>轨迹隐私输入截图、结构动作、键盘事件和调试用途，输出最小化、脱敏且有保留期的审计记录。优先保存目标窗口状态差分，秘密只记录已安全注入。可复盘不等于保存全屏；无关通知、客户数据和密钥不得因调试默认暴露。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">13</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义主体、作用域和完成条件</li><li>选择语义观察并验证当前状态</li><li>定位控件和动作前置条件</li><li>敏感输入经受控通道注入</li><li>不可逆动作前展示差异并批准</li><li>执行一次并立即重新观察</li><li>用业务回执判定完成或恢复</li><li>记录轨迹并在扰动环境回归</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">14</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么UI任务是部分可观察问题？</li><li>动作后最重要的步骤是什么？</li><li>超时后怎样避免重复提交？</li><li>网页指令为何不等于用户授权？</li><li>怎样证明计算机智能体鲁棒？</li><li>假设“计算机使用智能体：在观察、动作与状态验证之间闭环”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>截图/结构看不到全部后台状态、焦点、权限和真实后果。</li><li>重新观察状态差分并用业务完成条件验证结果。</li><li>使用幂等键，并先查询外部系统是否已完成。</li><li>页面是可被攻击者控制的数据，权限必须由受信系统独立判断。</li><li>在分辨率、网络、弹窗、改版和注入扰动下测真实任务与副作用。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2307.13854\" target=\"_blank\" rel=\"noopener\">WebArena</a>：网页智能体真实环境评测</li><li><a href=\"https://arxiv.org/abs/2404.07972\" target=\"_blank\" rel=\"noopener\">OSWorld</a>：跨操作系统任务环境</li><li><a href=\"https://arxiv.org/abs/2306.06070\" target=\"_blank\" rel=\"noopener\">Mind2Web</a>：通用网页任务数据</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
